css:
th, td{
    border:1px solid gray;
    font-size:13px;
    line-height:1;
}
.print-format p {
    margin: 1px 0px 0px !important;
}
.no-border{
    border:unset;
}
.border-style{
    border: 1px solid gray; 
}

.print-format .letter-head {
  margin-bottom: 10px !important;
}
.border-top-style{
    border: 1px solid gray;
}
.border-bottom-style{
    border: 1px solid gray;
}
.border-group{
    text-align: center;
    border-bottom: 1px solid gray;
    padding-bottom: 3px;
    width:100%;
}
.font_weight{
    font-weight:600;
}
td{
    font-size:12px;
}
